// ============================================
// VALIDATION INPUT - MCP Qdrant Save
// RFC-014 Extraction Pattern
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- OPTIONAL context fields (for tracing, NO validation errors if missing) ---
const userId = body.user_id || ctx.user_id || body.discord_user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- REQUIRED webhook parameters ---
const entityType = body.entity_type || ctx.entity_type;
const data = body.data || ctx.data;
const qdrantHost = body.qdrant_host || ctx.qdrant_host;
const qdrantPort = body.qdrant_port || ctx.qdrant_port;
const qdrantCollection = body.qdrant_collection || ctx.qdrant_collection;
const openaiApiKey = body.openai_api_key || ctx.openai_api_key;

if (!entityType) {
  errors.push('entity_type requis');
}
if (!data) {
  errors.push('data requis');
}
if (!qdrantHost) {
  errors.push('qdrant_host requis');
}
if (!qdrantPort) {
  errors.push('qdrant_port requis');
}
if (!qdrantCollection) {
  errors.push('qdrant_collection requis');
}
if (!openaiApiKey) {
  errors.push('openai_api_key requis');
}

// Optional parameters
const storeEmbedding = body.store_embedding !== false;
const llmMetadata = body.llm_metadata || ctx.llm_metadata || {};

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

// Build text for embedding (generic)
const embeddingText = [
  data.title || '',
  data.description || '',
  (data.tags || []).join(' '),
  (data.ingredients || []).map(i => typeof i === 'string' ? i : i.name).join(' '),
  data.content || ''
].join(' ').trim();

const qdrantUrl = `http://${qdrantHost}:${qdrantPort}`;

return {
  valid: true,
  entity_type: entityType,
  data: data,
  embedding_text: embeddingText,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  store_embedding: storeEmbedding,
  llm_metadata: llmMetadata,
  qdrant_url: qdrantUrl,
  qdrant_collection: qdrantCollection,
  openai_api_key: openaiApiKey,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

const input = $input.first().json;
const prevData = $('Validate Input').first().json;

function generateUUID() {
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
      var r = Math.random() * 16 | 0;
      var v = c === 'x' ? r : (r & 0x3 | 0x8);
      return v.toString(16);
    });
  }

  if (input.error) {
    return [{
      json: {
        ...prevData,
        embedding: null,
        embedding_error: input.error.message
      }
    }];
  }

  const embedding = input.data?.[0]?.embedding;

  return [{
    json: {
      ...prevData,
      embedding,
      point_id: generateUUID()
    }
  }];

// ============================================
// FORMAT OUTPUT - MCP Qdrant Save
// With _trace for RFC-014 compliance
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const qdrantData = $('Prepare Qdrant').first().json;
const startTime = prevData.startTime || Date.now();

// --- Context fields for traceability ---
const userId = prevData.user_id;
const guildId = prevData.guild_id;
const userRequest = prevData.user_request;

try {
  if (input.error) {
    return [{
      json: {
        success: false,
        _trace: {
          service_response: input,
          provider: 'api',
          mode: 'error',
          latency_ms: Date.now() - startTime,
          user_id: userId,
          guild_id: guildId,
          user_request: userRequest
        },
        error: {
          code: 'API_ERROR',
          message: input.error.message || 'API save failed',
          http_status: input.error.status || 500
        },
        user_id: userId,
        guild_id: guildId,
        user_request: userRequest
      }
    }];
  }

  return [{
    json: {
      success: true,
      data: {
        entity_id: input.data?.id || input.id,
        entity_type: prevData.entity_type,
        stored_in_qdrant: !!qdrantData.embedding,
        qdrant_point_id: qdrantData.point_id || null,
        entity: prevData.data
      },
      _trace: {
        service_response: { api: input, qdrant: qdrantData.embedding ? 'stored' : 'skipped' },
        provider: 'api+qdrant',
        mode: 'success',
        latency_ms: Date.now() - startTime,
        user_id: userId,
        guild_id: guildId,
        user_request: userRequest
      },
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      _trace: {
        service_response: { error: e.message },
        provider: 'api',
        mode: 'error',
        latency_ms: Date.now() - startTime,
        user_id: userId,
        guild_id: guildId,
        user_request: userRequest
      },
      error: {
        code: 'PROCESS_ERROR',
        message: 'Failed to process save: ' + e.message,
        http_status: 500
      },
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest
    }
  }];
}

const validateInput = $('Validate Input').first().json;
const prepareQdrant = $('Prepare Qdrant').first().json;

return [{
  json: {
    discord_user_id: validateInput.user_id,
    data: validateInput.data,
    qdrant_point_id: prepareQdrant.point_id,
    llm_metadata: validateInput.llm_metadata || {}
  }
}];
